class Solution {
    public int determineMinimumCharactersToAppend(String searchWord, String resultWord) {
        int j = 0, m = resultWord.length();
        for (int i = 0; i < searchWord.length() && j < m; i++) {
            if (searchWord.charAt(i) == resultWord.charAt(j)) j++;
        }
        return m - j;
    }
}

class Solution {
public:
    int determineMinimumCharactersToAppend(string searchWord, string resultWord) {
        int j = 0, m = resultWord.size();
        for (char c : searchWord) {
            if (j < m && c == resultWord[j]) j++;
        }
        return m - j;
    }
};
